/* Generated by Trae Work — 图表初始化：链路构成 / 响应体量级 / 实验样本量 / 故障时间窗 */
(function () {
  'use strict';

  var rootStyles = getComputedStyle(document.documentElement);

  function token(name, fallback) {
    var value = rootStyles.getPropertyValue(name);
    value = value ? value.trim() : '';
    return value || fallback;
  }

  var palette = {
    series1: token('--chart-series-1', '#0969DA'),
    other: token('--chart-other', '#D0D7DE'),
    positive: token('--chart-positive', '#1A7F37'),
    warning: token('--chart-warning', '#9A6700'),
    negative: token('--chart-negative', '#CF222E'),
    grid: token('--chart-grid', 'rgba(27, 31, 36, 0.12)'),
    axis: token('--chart-axis', '#636C76'),
    label: token('--chart-label', '#636C76'),
    tooltipBg: token('--chart-tooltip-bg', '#FFFFFF'),
    border: token('--page-border', '#D0D7DE'),
    text: token('--page-text', '#1B1F24'),
    textMuted: token('--page-text-muted', '#636C76')
  };

  var onLabel = '#FFFFFF';

  function tooltipSkin() {
    return {
      appendToBody: true,
      backgroundColor: palette.tooltipBg,
      borderColor: palette.border,
      borderWidth: 1,
      padding: [8, 12],
      textStyle: { color: palette.text, fontSize: 12 }
    };
  }

  function formatBytes(value) {
    return String(value).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + ' B';
  }

  var charts = [];

  function renderEmptyState(container, message) {
    container.innerHTML = '';
    var note = document.createElement('p');
    note.className = 'chart__empty';
    note.textContent = message;
    container.appendChild(note);
  }

  function mount(id, buildOption, emptyMessage) {
    var container = document.getElementById(id);
    if (!container) return;
    if (!window.echarts) {
      renderEmptyState(container, emptyMessage);
      return;
    }
    var chart = window.echarts.init(container, null, { renderer: 'svg' });
    chart.setOption(buildOption());
    charts.push(chart);
  }

  /* ---------- 图 4：链路类型与结果构成 ---------- */
  /* 注：正文中图 2 为响应体量级、图 3 为实验样本量，本图为图 4。 */

  var OK_NAME = '返回 200（正常）';
  var FAIL_NAME = '返回 502（故障）';

  function buildRouteOption() {
    var categories = [
      '一跳直达电信边缘\n本地对照组实验 · 55 次请求',
      '两跳：电信边缘 → 移动缓存\n15:14 故障 · 1 次请求',
      '两跳：电信边缘 → 移动缓存\n15:19 故障 · 1 次请求'
    ];
    var okPercent = [100, 0, 0];
    var failPercent = [0, 100, 100];
    var okCount = [55, 0, 0];
    var failCount = [0, 1, 1];

    return {
      animation: false,
      color: [palette.positive, palette.negative],
      grid: { left: 4, right: 20, top: 34, bottom: 4, containLabel: true },
      legend: {
        data: [OK_NAME, FAIL_NAME],
        top: 0,
        left: 0,
        itemWidth: 12,
        itemHeight: 12,
        itemGap: 16,
        icon: 'roundRect',
        textStyle: { color: palette.textMuted, fontSize: 12 }
      },
      tooltip: {
        trigger: 'axis',
        axisPointer: { type: 'shadow' },
        backgroundColor: palette.tooltipBg,
        borderColor: palette.border,
        borderWidth: 1,
        padding: [8, 12],
        appendToBody: true,
        textStyle: { color: palette.text, fontSize: 12 },
        formatter: function (params) {
          if (!params || !params.length) return '';
          var lines = [params[0].name.replace(/\n/g, '　')];
          for (var i = 0; i < params.length; i += 1) {
            var item = params[i];
            var counts = item.seriesIndex === 0 ? okCount : failCount;
            lines.push(item.marker + item.seriesName + '：' + counts[item.dataIndex] + ' 次（占 ' + item.value + '%）');
          }
          return lines.join('<br>');
        }
      },
      xAxis: {
        type: 'value',
        min: 0,
        max: 100,
        axisLine: { show: false },
        axisTick: { show: false },
        splitLine: { lineStyle: { color: palette.grid } },
        axisLabel: { color: palette.label, fontSize: 11, formatter: '{value}%' }
      },
      yAxis: {
        type: 'category',
        data: categories,
        axisLine: { show: false },
        axisTick: { show: false },
        axisLabel: { color: palette.label, fontSize: 12, lineHeight: 16, margin: 12 }
      },
      series: [
        {
          name: OK_NAME,
          type: 'bar',
          stack: 'result',
          barWidth: 24,
          itemStyle: { color: palette.positive, borderRadius: 4 },
          label: {
            show: true,
            position: 'inside',
            color: onLabel,
            fontSize: 11,
            formatter: function (p) { return p.value > 0 ? p.value + '%' : ''; }
          },
          data: okPercent
        },
        {
          name: FAIL_NAME,
          type: 'bar',
          stack: 'result',
          barWidth: 24,
          itemStyle: { color: palette.negative, borderRadius: 4 },
          label: {
            show: true,
            position: 'inside',
            color: onLabel,
            fontSize: 11,
            formatter: function (p) { return p.value > 0 ? p.value + '%' : ''; }
          },
          data: failPercent
        }
      ]
    };
  }

  /* ---------- 图 2：响应体量级对照 ---------- */

  function buildBodySizeOption() {
    var rows = [
      { name: '502 网关错误页\n故障响应 · Content-Length', value: 574, color: palette.negative },
      { name: '200 校验壳页\n复测取样 · 解压后', value: 6333, color: palette.series1 },
      { name: '200 校验壳页\n另一次取样 · 解压后', value: 72914, color: palette.series1 }
    ];

    return {
      animation: false,
      grid: { left: 4, right: 64, top: 12, bottom: 4, containLabel: true },
      tooltip: Object.assign(tooltipSkin(), {
        trigger: 'item',
        formatter: function (p) {
          return p.name.replace(/\n/g, '　') + '<br>' + formatBytes(p.value) + '（对数刻度）';
        }
      }),
      xAxis: {
        type: 'value',
        logBase: 10,
        min: 100,
        max: 100000,
        axisLine: { show: false },
        axisTick: { show: false },
        splitLine: { lineStyle: { color: palette.grid } },
        axisLabel: {
          color: palette.label,
          fontSize: 11,
          formatter: function (v) { return v >= 1000 ? (v / 1000) + 'k' : v; }
        }
      },
      yAxis: {
        type: 'category',
        data: rows.map(function (row) { return row.name; }),
        axisLine: { show: false },
        axisTick: { show: false },
        axisLabel: { color: palette.label, fontSize: 12, lineHeight: 16, margin: 12 }
      },
      series: [
        {
          type: 'bar',
          barWidth: 22,
          itemStyle: { borderRadius: 4 },
          label: {
            show: true,
            position: 'right',
            color: palette.textMuted,
            fontSize: 11,
            formatter: function (p) { return formatBytes(p.value); }
          },
          data: rows.map(function (row) {
            return { value: row.value, itemStyle: { color: row.color } };
          })
        }
      ]
    };
  }

  /* ---------- 图 3：七轮实验样本量 ---------- */

  function buildSampleOption() {
    var rows = [
      { name: '第 1 轮 · curl 直连与经代理', value: 6 },
      { name: '第 2 轮 · curl 指定 HTTP/1.1', value: 3 },
      { name: '第 3 轮 · httpx 二乘二正交', value: 18 },
      { name: '第 4 轮 · curl_cffi 指纹模拟', value: 21 },
      { name: '第 5 轮 · Chrome 无头模式', value: 5 },
      { name: '第 6 轮 · Chrome 有界面', value: 2 },
      { name: '第 7 轮 · 只读审计（无请求）', value: 0 }
    ];

    return {
      animation: false,
      grid: { left: 4, right: 48, top: 12, bottom: 28, containLabel: true },
      tooltip: Object.assign(tooltipSkin(), {
        trigger: 'item',
        formatter: function (p) {
          return p.name + '<br>样本请求数：' + p.value + ' 次';
        }
      }),
      xAxis: {
        type: 'value',
        max: 24,
        interval: 6,
        name: '样本请求数（次）',
        nameLocation: 'end',
        nameGap: 10,
        nameTextStyle: { color: palette.label, fontSize: 11, align: 'right' },
        axisLine: { show: false },
        axisTick: { show: false },
        splitLine: { lineStyle: { color: palette.grid } },
        axisLabel: { color: palette.label, fontSize: 11 }
      },
      yAxis: {
        type: 'category',
        inverse: true,
        data: rows.map(function (row) { return row.name; }),
        axisLine: { show: false },
        axisTick: { show: false },
        axisLabel: { color: palette.label, fontSize: 12, margin: 12 }
      },
      series: [
        {
          type: 'bar',
          barWidth: 14,
          itemStyle: { borderRadius: 4 },
          label: {
            show: true,
            position: 'right',
            color: palette.textMuted,
            fontSize: 11,
            formatter: function (p) { return p.value + ' 次'; }
          },
          data: rows.map(function (row) {
            return {
              value: row.value,
              itemStyle: { color: row.value === 0 ? palette.other : palette.series1 }
            };
          })
        }
      ]
    };
  }

  /* ---------- 图 5：故障时间窗与访问时序 ---------- */

  function buildWindowOption() {
    function at(h, m, s) { return new Date(2026, 8, 29, h, m, s || 0).getTime(); }
    function pad(n) { return n < 10 ? '0' + n : String(n); }
    function clock(ms) {
      var d = new Date(ms);
      return pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
    }

    var axisMin = at(15, 5, 0);
    var axisMax = at(15, 42, 0);
    var winStart = at(15, 14, 17);
    var winEnd = at(15, 19, 6);

    var normalVisits = [at(15, 8, 7), at(15, 12, 30), at(15, 37, 14), at(15, 38, 54)];
    var failVisits = [at(15, 14, 18), at(15, 19, 8)];
    var unknownVisits = [at(15, 18, 36), at(15, 18, 38)];

    function points(list) {
      return list.map(function (ms) { return [ms, 1]; });
    }

    return {
      animation: false,
      grid: { left: 4, right: 24, top: 34, bottom: 4, containLabel: true },
      legend: {
        data: ['故障时间窗', '正常访问', '502 故障响应', '窗内访问（未单独留证）'],
        top: 0,
        left: 0,
        itemWidth: 12,
        itemHeight: 12,
        itemGap: 16,
        icon: 'roundRect',
        textStyle: { color: palette.textMuted, fontSize: 12 }
      },
      tooltip: Object.assign(tooltipSkin(), {
        trigger: 'item',
        formatter: function (p) {
          if (p.seriesName === '故障时间窗') {
            return '故障时间窗<br>' + clock(winStart) + ' – ' + clock(winEnd) + '（5 分 49 秒）';
          }
          return p.seriesName + '<br>' + clock(p.value[0]);
        }
      }),
      xAxis: {
        type: 'value',
        min: axisMin,
        max: axisMax,
        interval: 300000,
        axisLine: { show: false },
        axisTick: { show: false },
        splitLine: { lineStyle: { color: palette.grid } },
        axisLabel: {
          color: palette.label,
          fontSize: 11,
          formatter: function (v) {
            var d = new Date(v);
            return pad(d.getHours()) + ':' + pad(d.getMinutes());
          }
        }
      },
      yAxis: {
        type: 'category',
        inverse: true,
        data: ['故障时间窗', '页面访问时刻'],
        axisLine: { show: false },
        axisTick: { show: false },
        axisLabel: { color: palette.label, fontSize: 12, margin: 12 },
        splitLine: { lineStyle: { color: palette.grid } }
      },
      series: [
        {
          name: 'window-offset',
          type: 'bar',
          stack: 'window',
          barWidth: 22,
          silent: true,
          itemStyle: { color: 'transparent' },
          tooltip: { show: false },
          data: [winStart - axisMin]
        },
        {
          name: '故障时间窗',
          type: 'bar',
          stack: 'window',
          barWidth: 22,
          silent: true,
          itemStyle: { color: palette.negative, borderRadius: 4 },
          label: {
            show: true,
            position: 'inside',
            color: onLabel,
            fontSize: 11,
            formatter: '5 分 49 秒'
          },
          data: [winEnd - winStart]
        },
        {
          name: '正常访问',
          type: 'scatter',
          symbolSize: 12,
          itemStyle: { color: palette.positive },
          data: points(normalVisits)
        },
        {
          name: '502 故障响应',
          type: 'scatter',
          symbolSize: 12,
          itemStyle: { color: palette.negative },
          data: points(failVisits)
        },
        {
          name: '窗内访问（未单独留证）',
          type: 'scatter',
          symbolSize: 12,
          itemStyle: { color: palette.warning },
          data: points(unknownVisits)
        }
      ]
    };
  }

  /* ---------- 启动 ---------- */

  var EMPTY = {
    route: '图表库未能加载，本图数据见正文：一跳直达 55/55 返回 200，两跳路由 2/2 返回 502。',
    bodySize: '图表库未能加载，本图数据见正文：502 错误页正文 574 字节；200 校验壳页为 6333 字节（另一次取样 72914 字节）。',
    samples: '图表库未能加载，本图数据见正文表 4：六轮实验共 55 个请求样本，第 7 轮只读审计不产生请求。',
    window: '图表库未能加载，本图数据见下方时间线：故障时间窗为 15:14:17 至 15:19:06。'
  };

  function boot() {
    mount('chart-route-outcome', buildRouteOption, EMPTY.route);
    mount('chart-body-size', buildBodySizeOption, EMPTY.bodySize);
    mount('chart-experiment-samples', buildSampleOption, EMPTY.samples);
    mount('chart-incident-window', buildWindowOption, EMPTY.window);

    var resizeTimer = null;
    window.addEventListener('resize', function () {
      if (resizeTimer) window.clearTimeout(resizeTimer);
      resizeTimer = window.setTimeout(function () {
        for (var i = 0; i < charts.length; i += 1) charts[i].resize();
      }, 120);
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }
})();
